The regex `followUpTextRegex` is defined with the global (`g`) flag as a module-level constant. When using `.exec()` in a loop with a global regex, the `lastIndex` property persists between calls. If `parseFollowupsFromHtml` is called multiple times, the regex state may not be reset, causing the function to skip matches or produce incorrect results.

Reset the regex before use or create a new regex instance:

**Option 1: Reset before use**
```typescript
function parseFollowupsFromHtml(html: string): Followup[] | null {
    const followupListMatch = html.match(followUpListRegex);
    if (\!followupListMatch) {
        return null;
    }

    const followupListHtml = followupListMatch[0];
    const hasSelectedAttribute = followUpSelectedListRegex.test(followupListHtml);
    if (hasSelectedAttribute) {
        return [];
    }

    const followups: Followup[] = [];
    followUpTextRegex.lastIndex = 0; // Reset regex state
    let match = followUpTextRegex.exec(followupListHtml);
    while (match \!== null) {
        followups.push({text: match[1]});
        match = followUpTextRegex.exec(followupListHtml);
    }
    return followups;
}
```

**Option 2: Create new regex instance (recommended)**
```typescript
function parseFollowupsFromHtml(html: string): Followup[] | null {
    const followupListMatch = html.match(followUpListRegex);
    if (\!followupListMatch) {
        return null;
    }

    const followupListHtml = followupListMatch[0];
    const hasSelectedAttribute = followUpSelectedListRegex.test(followupListHtml);
    if (hasSelectedAttribute) {
        return [];
    }

    const followups: Followup[] = [];
    const regex = /<followup><followup-text>([^<]*)<\/followup-text><\/followup>/gi;
    let match = regex.exec(followupListHtml);
    while (match \!== null) {
        followups.push({text: match[1]});
        match = regex.exec(followupListHtml);
    }
    return followups;
}
```

